+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Filter applied by the backend.
+ *
+ * @param name     whitespace-separated terms; each must occur in the first or last name,
+ *                 ignoring case and accents
+ * @param statuses statuses to keep; empty means all
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name.trim();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of() : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    public boolean matches(Customer c) {
+        if (!statuses.isEmpty() && !statuses.contains(c.status())) {
+            return false;
+        }
+        if (name.isEmpty()) {
+            return true;
+        }
+        String first = normalize(c.firstName());
+        String last = normalize(c.lastName());
+        return Arrays.stream(normalize(name).split("\\s+"))
+                .filter(t -> !t.isEmpty())
+                .allMatch(t -> first.contains(t) || last.contains(t));
+    }
+
+    static String normalize(String s) {
+        return Normalizer.normalize(s, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
